def match(orders):
    import heapq

    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}       # id -> {'side','price','qty','seq','active'}
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book and book[oid]['qty'] > 0 and book[oid].get('active', True):
                book[oid]['qty'] = 0
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                info = book.get(top_id)
                if info is None or info['qty'] <= 0 or not info.get('active', True):
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and top_price > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    heapq.heappop(sell_heap)

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                info = book.get(top_id)
                if info is None or info['qty'] <= 0 or not info.get('active', True):
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and top_price < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    heapq.heappop(buy_heap)

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

